1	// Per-node capacity / utilization math for the node-capacity warning feature.
2	//
3	// Plain (non-"use server") module — safe to import from admin server components
4	// (the Compute-nodes and Web-hosting pages render bars off it) AND from the
5	// worker sweep (worker/monitor.ts → nodeCapacitySweep raises/clears NodeAlerts
6	// off it). No mutations here; the alert lifecycle lives in the worker so this
7	// file stays a pure-ish reader other surfaces can share, exactly like the
8	// read-only helpers in lib/monitoring.ts.
9	//
10	// TWO NODE TYPES, ONE MODEL. Nxeon schedules customer VMs onto Proxmox `Node`s
11	// and shared-hosting accounts onto `HostingNode`s. Both fill up and both refuse
12	// new work when they do, so both are reduced to the same shape: a list of
13	// per-DIMENSION utilization percentages (CPU/RAM/DISK for Proxmox, ACCOUNTS/DISK
14	// for hosting) that the thresholds below turn into OK / WARN / CRITICAL.
15	//
16	// ALLOCATION vs REAL USAGE. For each dimension we take the WORSE of two numbers:
17	//   - allocation: what the DB has COMMITTED to the node (sum of every server's
18	//     plan RAM/disk/vCPU, or the account count). This is what makes the NEXT
19	//     provision fail — a node can be 100% committed while barely warm.
20	//   - real usage: what Proxmox actually reports in use right now (RAM/CPU/disk),
21	//     which is what makes a node DEGRADE.
22	// Warning on max(alloc, real) means we fire on whichever ceiling is hit first,
23	// which is the honest "add a node before this bites" signal the feature exists
24	// to give.
25	
26	import { db } from "./db";
27	import type { NodeProvider } from "@prisma/client";
28	import { nodeRamUsage, nodeStorageUsage, backupSummary, BACKUP_STALE_MS, type NodeRam, type StorageUsage } from "./monitoring";
29	import { effectiveDiskGB, baseDiskGBFor } from "./extra-disk";
30	import { getSettingInt } from "./settings";
31	import { nodeTemplateVmids, nodesWithTemplate } from "./node-templates";
32	import { logError } from "./log";
33	import { SANDBOX } from "./sandbox";
34	import { nodeRamGuard } from "./node-ram-guard";
35	import { ramGuardMode } from "./vm-memory-policy";
36	// severityFor/capBarColor/CapSeverity/NodeThresholds live in capacity-severity.ts
37	// (a dependency-free, client-safe module) and are re-exported here unchanged —
38	// see that file's doc comment for why they were split out.
39	import { severityFor, capBarColor, isGenuineSeverityChange, type CapSeverity, type NodeThresholds } from "./capacity-severity";
40	
41	export { severityFor, capBarColor, isGenuineSeverityChange, type CapSeverity, type NodeThresholds };
42	
43	const MB = 1024 * 1024;
44	const GB = 1024 ** 3;
45	
46	export type CapDimension = "CPU" | "RAM" | "DISK" | "ACCOUNTS" | "BACKUP";
47	export type NodeKind = "PROXMOX" | "HOSTING";
48	
49	export const NODE_CAP_DEFAULT_WARN = 80;
50	export const NODE_CAP_DEFAULT_CRIT = 90;
51	
52	/**
53	 * Hysteresis: an OPEN alert only auto-resolves once utilization falls this many
54	 * points BELOW the WARN threshold. Without the gap a node parked right on the
55	 * line (79 ⇄ 81) would flap open/closed every sweep and bury the operator in
56	 * churn. Env-overridable for tuning without a redeploy.
57	 */
58	export const NODE_CAP_RESOLVE_MARGIN = Number(process.env.NXEON_NODE_ALERT_RESOLVE_MARGIN ?? 5);
59	
60	/**
61	 * A persistent (unchanged-severity) condition re-notifies at most once per this
62	 * many hours — the debounce that stops "node stuck at 92%" emailing ops every
63	 * 10-minute sweep. A NEW alert and a WARN⇄CRITICAL change always notify
64	 * immediately regardless of the cooldown.
65	 */
66	export const NODE_CAP_COOLDOWN_HOURS = Number(process.env.NXEON_NODE_ALERT_COOLDOWN_HOURS ?? 6);
67	
68	/**
69	 * Every server status EXCEPT DELETING still holds committed capacity on its node
70	 * — its VM (and its RAM/disk reservation) exists until the delete completes. This
71	 * matches the exclusion the existing scheduler and infra pages already use
72	 * (`status: { not: "DELETING" }`), so the utilization shown here agrees with what
73	 * scheduleNode commits against.
74	 */
75	const VPS_COMMITTED_EXCLUDE = ["DELETING"] as const;
76	/** Hosting-account statuses that still occupy a slot / quota on their node. */
77	const HOSTING_LIVE_STATUSES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
78	
79	/**
80	 * Resolve the admin-configured thresholds, clamped so they are always usable:
81	 * both in 1..100, and CRITICAL never below WARN (a CRITICAL under WARN would make
82	 * the amber band unreachable and every warn instantly read critical).
83	 */
84	export async function nodeThresholds(): Promise<NodeThresholds> {
85	  let warnPct = await getSettingInt("node_warn_pct", NODE_CAP_DEFAULT_WARN);
86	  let critPct = await getSettingInt("node_critical_pct", NODE_CAP_DEFAULT_CRIT);
87	  if (!Number.isFinite(warnPct) || warnPct < 1 || warnPct > 100) warnPct = NODE_CAP_DEFAULT_WARN;
88	  if (!Number.isFinite(critPct) || critPct < 1 || critPct > 100) critPct = NODE_CAP_DEFAULT_CRIT;
89	  if (critPct < warnPct) critPct = warnPct;
90	  return { warnPct, critPct };
91	}
92	
93	
94	/** The percent below which an OPEN alert is allowed to auto-resolve. */
95	export function resolveFloor(t: NodeThresholds): number {
96	  return Math.max(0, t.warnPct - NODE_CAP_RESOLVE_MARGIN);
97	}
98	
99	export type DimUtil = {
100	  dimension: CapDimension;
101	  /** The value thresholded — the worse of allocation and real usage. */
102	  pct: number;
103	  /** DB-committed percent (null when the dimension has no allocation basis). */
104	  allocPct: number | null;
105	  /** Live-usage percent from Proxmox (null when unreachable / not applicable). */
106	  realPct: number | null;
107	  /** Short human breakdown, e.g. "48 / 56 GB committed · 61% used". */
108	  detail: string;
109	  /** `allocPct`'s own absolute breakdown alone, e.g. "48 / 56 GB" — for UIs that
110	   *  render committed and used as two separate rows instead of one combined
111	   *  line. Null exactly when `allocPct` is null. */
112	  allocDetail: string | null;
113	  /** `realPct`'s own absolute breakdown alone, e.g. "34 GB used" — same
114	   *  pairing as `allocDetail`, null exactly when `realPct` is null. */
115	  realDetail: string | null;
116	};
117	
118	export type NodeUtil = {
119	  kind: NodeKind;
120	  id: string;
121	  name: string;
122	  enabled: boolean;
123	  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
124	  reachable: boolean;
125	  dims: DimUtil[];
126	  /** Worst dimension percent across `dims` (0 when there are none). */
127	  worstPct: number;
128	  severity: CapSeverity;
129	};
130	
131	function pct(part: number, whole: number): number | null {
132	  if (!(whole > 0)) return null;
133	  return (part / whole) * 100;
134	}
135	
136	/** Combine allocation + real into the thresholded value (worse of the two). */
137	function worse(allocPct: number | null, realPct: number | null): number {
138	  return Math.max(allocPct ?? 0, realPct ?? 0);
139	}
140	
141	function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
142	  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
143	  return { worstPct, severity: severityFor(worstPct, t) };
144	}
145	
146	// ---------------------------------------------------------------------------
147	// Proxmox compute nodes
148	// ---------------------------------------------------------------------------
149	
150	/**
151	 * Utilization for every registered Proxmox node.
152	 *
153	 * RAM is always computable (allocation from `Node.capacityRamMB` + the sum of
154	 * each live server's `plan.ramMB`; real usage from the node status endpoint when
155	 * reachable). CPU and DISK need Proxmox to be reachable for their denominator
156	 * (physical thread count / storage pool size), so on an unreachable node they are
157	 * simply omitted rather than guessed — `reachable:false` tells the UI and the
158	 * sweep to treat their absence as "unknown", never as "recovered".
159	 */
160	export async function proxmoxNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
161	  const nodes = await db.node.findMany({
162	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
163	    include: {
164	      servers: {
165	        where: { status: { notIn: [...VPS_COMMITTED_EXCLUDE] } },
166	        select: {
167	          extraDiskGB: true,
168	          plan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
169	          gamePlan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
170	        },
171	      },
172	    },
173	  });
174	
175	  // Real usage, best-effort. Keyed by node NAME — nodeRamUsage/nodeStorageUsage
176	  // label every row with `Node.name` (see lib/monitoring.ts nodeTargets).
177	  let ramRows: NodeRam[] = [];
178	  let storageRows: StorageUsage[] = [];
179	  let backupRows: Awaited<ReturnType<typeof backupSummary>> = [];
180	  try {
181	    ramRows = await nodeRamUsage();
182	  } catch {
183	    /* leave empty — every node reads unreachable */
184	  }
185	  try {
186	    storageRows = await nodeStorageUsage();
187	  } catch {
188	    /* leave empty */
189	  }
190	  try {
191	    backupRows = await backupSummary();
192	  } catch {
193	    /* leave empty — BACKUP dim simply omitted below, same as an unreachable CPU/DISK */
194	  }
195	  const ramByNode = new Map(ramRows.map((r) => [r.node, r]));
196	  const backupByNode = new Map(backupRows.map((b) => [b.node, b]));
197	
198	  return nodes.map((n) => {
199	    // A game server's real commitment is its game plan's, not the (larger)
200	    // base VPS plan it rides on — see lib/extra-disk.ts's baseDiskGBFor.
201	    const committedRamMB = n.servers.reduce((s, sv) => s + (sv.gamePlan?.ramMB ?? sv.plan.ramMB), 0);
202	    const committedDiskGB = n.servers.reduce(
203	      (s, sv) => s + effectiveDiskGB(baseDiskGBFor(sv), sv.extraDiskGB),
204	      0,
205	    );
206	    const committedVcpu = n.servers.reduce((s, sv) => s + (sv.gamePlan?.cpuCores ?? sv.plan.cpuCores), 0);
207	
208	    const real = ramByNode.get(n.name);
209	    const reachable = !!real?.reachable;
210	    // The node's own VM-disk pool (storageNvme) is the disk denominator.
211	    const vmStorage = storageRows.find((s) => s.node === n.name && s.storage === n.storageNvme);
212	
213	    const dims: DimUtil[] = [];
214	
215	    // RAM — allocation always available; real when reachable.
216	    {
217	      const allocPct = pct(committedRamMB, n.capacityRamMB);
218	      const realPct = reachable && real ? real.ratio * 100 : null;
219	      const p = worse(allocPct, realPct);
220	      const allocDetail = `${(committedRamMB / 1024).toFixed(0)} / ${(n.capacityRamMB / 1024).toFixed(0)} GB`;
221	      const realDetail = realPct !== null && real ? `${(real.used / GB).toFixed(0)} GB used` : null;
222	      const parts = [`${allocDetail} committed`];
223	      if (realDetail) parts.push(realDetail);
224	      dims.push({ dimension: "RAM", pct: p, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
225	    }
226	
227	    // CPU — real usage is the signal (vCPU is normally overcommitted, so an
228	    // allocation ratio is context, not an alarm). Only present when reachable.
229	    if (reachable && real) {
230	      const realPct = real.cpu * 100;
231	      const allocPct = real.cores > 0 ? (committedVcpu / real.cores) * 100 : null;
232	      const allocDetail = allocPct !== null ? `${committedVcpu} vCPU / ${real.cores} threads` : null;
233	      const realDetail = `${Math.round(realPct)}% used`;
234	      const parts = [realDetail];
235	      if (allocDetail) parts.push(`${allocDetail} (${Math.round(allocPct!)}% committed)`);
236	      // CPU is thresholded on REAL load only; overcommit alloc is informational.
237	      dims.push({ dimension: "CPU", pct: realPct, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
238	    }
239	
240	    // DISK — needs the pool size from Proxmox. Allocation = committed effective
241	    // disk vs pool total; real = pool used vs pool total. Worse of the two.
242	    if (vmStorage?.reachable && vmStorage.total > 0) {
243	      const allocPct = pct(committedDiskGB * GB, vmStorage.total);
244	      const realPct = vmStorage.ratio * 100;
245	      const p = worse(allocPct, realPct);
246	      const allocDetail = `${committedDiskGB} GB / ${(vmStorage.total / GB).toFixed(0)} GB`;
247	      const realDetail = `${(vmStorage.ratio * (vmStorage.total / GB)).toFixed(0)} GB used`;
248	      dims.push({
249	        dimension: "DISK",
250	        pct: p,
251	        allocPct,
252	        realPct,
253	        detail: `${allocDetail} committed · ${Math.round(realPct)}% used`,
254	        allocDetail,
255	        realDetail,
256	      });
257	    }
258	
259	    // BACKUP — no allocation concept; thresholded on how stale the newest backup
260	    // is versus BACKUP_STALE_MS (so it crosses WARN/CRITICAL at 80%/90% of the
261	    // staleness window, reusing the same admin-configured thresholds as the other
262	    // dimensions). A node whose storage answers but shows zero backups EVER is
263	    // treated as maximally stale (100%) — that is precisely the "silently-broken
264	    // schedule on a node nobody's watching" case this dimension exists to catch.
265	    // Omitted entirely when the storage itself is unreachable — unknown, not OK.
266	    {
267	      const b = backupByNode.get(n.name);
268	      if (b?.reachable) {
269	        const ageMs = b.newestCtime !== null ? Date.now() - b.newestCtime * 1000 : null;
270	        const p = ageMs === null ? 100 : Math.min(100, (ageMs / BACKUP_STALE_MS) * 100);
271	        const detail =
272	          ageMs === null
273	            ? `No backups found on this node's storage (${b.count} on disk).`
274	            : `Newest backup ${Math.round(ageMs / 3_600_000)}h old · ${b.count} on disk (stale past ${Math.round(BACKUP_STALE_MS / 3_600_000)}h).`;
275	        dims.push({ dimension: "BACKUP", pct: p, allocPct: null, realPct: p, detail, allocDetail: null, realDetail: detail });
276	      }
277	    }
278	
279	    return {
280	      kind: "PROXMOX" as const,
281	      id: n.id,
282	      name: n.name,
283	      enabled: n.enabled,
284	      reachable,
285	      dims,
286	      ...rollup(dims, t),
287	    };
288	  });
289	}
290	
291	// ---------------------------------------------------------------------------
292	// Shared-hosting nodes
293	// ---------------------------------------------------------------------------
294	
295	/**
296	 * Utilization for every HostingNode. Purely DB-derived (the accounts and their
297	 * quotas live in our own tables), so it is always reachable:
298	 *   - ACCOUNTS: live account count vs `HostingNode.maxAccounts` — the hard
299	 *     scheduler cap; the next account is refused once it's full.
300	 *   - DISK: worse of committed quota (Σ diskQuotaMB) and measured usage
301	 *     (Σ diskUsedMB, filled by hostingUsageSweep) vs `diskTotalGB`.
302	 */
303	export async function hostingNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
304	  const nodes = await db.hostingNode.findMany({ orderBy: { name: "asc" } });
305	
306	  return Promise.all(
307	    nodes.map(async (n) => {
308	      const [count, agg] = await Promise.all([
309	        db.hostingAccount.count({
310	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
311	        }),
312	        db.hostingAccount.aggregate({
313	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
314	          _sum: { diskQuotaMB: true, diskUsedMB: true },
315	        }),
316	      ]);
317	
318	      const totalDiskMB = n.diskTotalGB * 1024;
319	      const quotaMB = agg._sum.diskQuotaMB ?? 0;
320	      const usedMB = agg._sum.diskUsedMB ?? 0;
321	
322	      const dims: DimUtil[] = [];
323	
324	      // ACCOUNTS
325	      {
326	        const allocPct = pct(count, n.maxAccounts);
327	        const p = allocPct ?? 0;
328	        const allocDetail = `${count} / ${n.maxAccounts} accounts`;
329	        dims.push({
330	          dimension: "ACCOUNTS",
331	          pct: p,
332	          allocPct,
333	          realPct: null,
334	          detail: allocDetail,
335	          allocDetail,
336	          realDetail: null,
337	        });
338	      }
339	
340	      // DISK
341	      {
342	        const allocPct = pct(quotaMB, totalDiskMB);
343	        const realPct = pct(usedMB, totalDiskMB);
344	        const p = worse(allocPct, realPct);
345	        const allocDetail = `${(quotaMB / 1024).toFixed(0)} GB / ${n.diskTotalGB} GB`;
346	        const realDetail = realPct !== null ? `${(usedMB / 1024).toFixed(0)} GB used` : null;
347	        const parts = [`${allocDetail} quota`];
348	        if (realDetail) parts.push(realDetail);
349	        dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · "), allocDetail, realDetail });
350	      }
351	
352	      return {
353	        kind: "HOSTING" as const,
354	        id: n.id,
355	        name: n.name,
356	        enabled: n.enabled,
357	        reachable: true,
358	        dims,
359	        ...rollup(dims, t),
360	      };
361	    }),
362	  );
363	}
364	
365	/** Every node (both kinds) with its utilization, plus the resolved thresholds. */
366	export async function allNodeUtil(): Promise<{ thresholds: NodeThresholds; nodes: NodeUtil[] }> {
367	  const thresholds = await nodeThresholds();
368	  const [proxmox, hosting] = await Promise.all([
369	    proxmoxNodeUtil(thresholds),
370	    hostingNodeUtil(thresholds),
371	  ]);
372	  return { thresholds, nodes: [...proxmox, ...hosting] };
373	}
374	
375	/**
376	 * Pick the best Proxmox node for a new server of `planRamMB`, when the
377	 * customer didn't choose a location explicitly. Bin-packs onto whichever
378	 * ONLINE, enabled node has the most free RAM after projecting this VM onto
379	 * it, staying under the CRITICAL threshold when any node can (falling back to
380	 * least-bad if every node is already critical).
381	 *
382	 * THIRD copy, consolidated here. This existed as two near-identical private
383	 * copies — `lib/order.ts` (VPS orders) and `lib/actions-nxcloud.ts` (NxCloud
384	 * orders) — and `lib/game-order.ts`'s game-server order path never called
385	 * either one at all: it creates its `Server` row with no `nodeId`, so every
386	 * game server ever ordered falls through `worker/index.ts`'s `nodeFor()`
387	 * fallback (`server.node ?? primary node`) and lands on the PRIMARY node
388	 * regardless of its actual load. Confirmed live: `primary` sits at 84% real
389	 * RAM and 200% committed CPU while other nodes are comparatively idle, and
390	 * every game server in production has `nodeId: null`. Fixed by giving
391	 * `game-order.ts` the same real scheduler VPS/NxCloud orders already use,
392	 * rather than writing a fourth copy or leaving it unscheduled.
393	 *
394	 * Returns null when no node qualifies — including (since 2026-10-01) when
395	 * the live RAM guard refuses every candidate. Callers must treat null as
396	 * "no capacity", never as "let the worker fall back to the primary".
397	 */
398	export type ScheduleOpts = {
399	  provider?: NodeProvider;
400	  region?: string;
401	  // templateVmid: the Proxmox template this order clones (OsTemplate.baseVmid
402	  // ?? vmid). When given, nodes that do not have it are never chosen — see
403	  // lib/node-templates.ts for the incident. Omitted = previous behaviour.
404	  templateVmid?: number | null;
405	  /**
406	   * REGION-BOUND placement (2026-10-01): refuse (null) when no candidate is
407	   * under the critical threshold instead of falling back to the "least-bad"
408	   * node. Used whenever a region was chosen/resolved, so a full region reports
409	   * "full" rather than quietly taking one more VM past its limit. Default
410	   * false keeps the legacy behaviour for the non-region callers.
411	   */
412	  strict?: boolean;
413	  /** Skip the per-call error logging (availability probes run on page render). */
414	  quiet?: boolean;
415	};
416	
417	export type ScheduleDetail = {
418	  node: Awaited<ReturnType<typeof db.node.findMany>>[number] | null;
419	  /** Candidates that would stay under the critical RAM threshold after this VM. */
420	  roomyCount: number;
421	  /** Candidates that survived the template/guard filters. */
422	  candidateCount: number;
423	  /** Lowest projected committed-RAM % across candidates (null = no candidates). */
424	  bestProjectedPct: number | null;
425	  /** warn-mode RAM guard flagged every candidate (log-only, but not "plenty of room"). */
426	  guardFlaggedAll: boolean;
427	};
428	
429	export async function scheduleNode(planRamMB: number, opts?: ScheduleOpts) {
430	  return (await scheduleNodeDetailed(planRamMB, opts)).node;
431	}
432	
433	/** scheduleNode plus the facts behind the decision (feeds regionAvailability). */
434	export async function scheduleNodeDetailed(planRamMB: number, opts?: ScheduleOpts): Promise<ScheduleDetail> {
435	  const none: ScheduleDetail = { node: null, roomyCount: 0, candidateCount: 0, bestProjectedPct: null, guardFlaggedAll: false };
436	  // Customer picks a REGION (e.g. "Singapore"), never a specific physical
437	  // node — multiple nodes can share one region (primary + node-3 are both
438	  // OVH/sgp1), and forcing a customer's choice onto one specific node meant
439	  // that node alone ever took new signups for that region, regardless of its
440	  // actual load relative to its sibling in the same region. Filtering here
441	  // (rather than a separate function) keeps this the single place "which
442	  // node wins" is decided, with or without a region constraint.
443	  const nodes = await db.node.findMany({
444	    where: {
445	      enabled: true,
446	      status: "ONLINE",
447	      // Distinct from `enabled` — a node can stay visible/online with its
448	      // existing servers running and still be excluded from taking NEW ones
449	      // (the admin Infrastructure page's per-node toggle).
450	      acceptsProvisions: true,
451	      ...(opts?.region ? { region: opts.region } : {}),
452	      ...(opts?.provider ? { provider: opts.provider } : {}),
453	    },
454	  });
455	  if (nodes.length === 0) return none;
456	  let candidates = nodes;
457	  if (opts?.templateVmid && !SANDBOX) {
458	    const tv = opts.templateVmid;
459	    const lookup = new Map(await Promise.all(nodes.map(async (n) => [n.id, await nodeTemplateVmids(n)] as const)));
460	    const { ok, missing } = nodesWithTemplate(nodes, tv, lookup);
461	    if (missing.length > 0 && !opts?.quiet) {
462	      logError("node-scheduler", new Error(`template ${tv} missing on ${missing.map((m) => m.name).join(", ")}`), {
463	        templateVmid: tv,
464	        excluded: missing.map((m) => m.name),
465	        note: "these nodes were skipped for this order; copy the template to them (scripts/onboard-node.sh) to restore capacity",
466	      });
467	    }
468	    if (ok.length === 0) return none;
469	    candidates = ok;
470	  }
471	  const loads = await Promise.all(
472	    candidates.map(async (n) => {
473	      const agg = await db.server.findMany({
474	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
475	        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
476	      });
477	      // A game server's real commitment is its game plan's ram, not the
478	      // (larger) base VPS plan it rides on — overstating every game server's
479	      // load here skews which node the scheduler picks for the NEXT one.
480	      const used = agg.reduce((s, r) => s + (r.gamePlan?.ramMB ?? r.plan.ramMB), 0);
481	      // Commitment AFTER this VM lands — that's what decides whether placing
482	      // here tips the node critical.
483	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
484	      return { node: n, free: n.capacityRamMB - used, projectedPct };
485	    }),
486	  );
487	  // LIVE RAM GUARD (2026-10-01). Customer VMs are pinned to their plan RAM
