    47	export async function readNodeRamSnapshot(node: NodeLike): Promise<{ snap: NodeRamSnapshot; vms: (ListedVm & { name?: string })[] }> {
    48	  const conn = pveFor({ apiUrl: node.apiUrl, pveNode: node.pveNode, tokenId: node.tokenId, tokenSecret: node.tokenSecret });
    49	  const [status, list] = await Promise.all([
    50	    timeout(conn.get(`/nodes/${node.pveNode}/status`), READ_TIMEOUT_MS, "node status"),
