    55	    rows.map(async (r) => {
    56	      const vmid = Number(r?.vmid);
    57	      const template = String(r?.template ?? "") === "1";
    58	      const status = String(r?.status ?? "");
    59	      const listedMB = Math.round(Number(r?.maxmem ?? 0) / MB);
