    63	      // current=1: the values the RUNNING VM has, not a pending change.
    64	      const cfg = await timeout(
    65	        conn.get(`/nodes/${node.pveNode}/qemu/${vmid}/config`, { current: 1 }),
    66	        READ_TIMEOUT_MS,
    67	        `config ${vmid}`,
    68	      );
