 * explicit region. Throws OrderError ("<Region> is full, nearest are ...") when
 * the region has no room — never silently picks another region. A specific
 * `nodeId` (admin/internal) skips it, as in placeOrder.
 */
export async function applyOrderRegion(intent: OrderIntent, userId: string): Promise<void> {
  if (intent.nodeId) return;
  const [plan, os] = await Promise.all([
    db.plan.findUnique({ where: { id: intent.planId }, select: { ramMB: true } }),
    db.osTemplate.findUnique({ where: { id: intent.osTemplateId }, select: { vmid: true, baseVmid: true } }),
  ]);
  if (!plan || !os) return; // quote/placeOrder report the real error
  const placement = await placeInRegion({
    ramMB: plan.ramMB,
    templateVmid: os.baseVmid ?? os.vmid,
    region: intent.region,
    provider: intent.provider,
    userId,
  });
  if (!placement.ok) {
    await logRegionRefusal(userId, "vps", placement);
    throw new OrderError(placement.message);
  }
  intent.regionSource = intent.region ? intent.regionSource ?? "explicit" : placement.source;
  intent.region = placement.region;
}

