/**
 * Would deploying `planId` push committed RAM past the oversell ceiling?
 * Returns { ok:false, reason } when the host cannot take the new server.
 */
export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true } });
  if (!plan) return { ok: false, reason: "Plan not found." };
  return capacityCheckRamMB(plan.ramMB);
}

/**
 * Would committing `addDiskGB` more of VM disk overflow the node's usable
 * storage? Mirrors `capacityCheck` but for disk: sums committed plan disk on
 * the node and compares against the usable NVMe pool times a safety ratio.
 *
 * Usable pool size is read live from Proxmox (`storageNvme` status) when the
 * node is reachable, falling back to `HOST_DISK_GB`. Pass `nodeId = null` to
 * check against all non-deleting servers / the primary node.
 */
export async function diskCapacityCheck(
  nodeId: string | null | undefined,
  addDiskGB: number
): Promise<{ ok: boolean; reason?: string }> {
  const servers = await db.server.findMany({
    where: { status: { not: "DELETING" }, ...(nodeId ? { nodeId } : {}) },
    select: { extraDiskGB: true, plan: { select: { diskGB: true } }, gamePlan: { select: { diskGB: true } } },
  });
  // Committed disk counts the EFFECTIVE size of every server (plan + purchased
  // extra), otherwise expansions would silently oversubscribe the pool. A
  // game server's real commitment is its game plan's, not the (larger) base
  // VPS plan it rides on.
  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(baseDiskGBFor(s), s.extraDiskGB), 0);

  // Resolve usable pool size + REAL usage — prefer the live Proxmox NVMe pool.
  let usableGB = HOST_DISK_GB;
  let freeGB: number | null = null; // real free space (total − used), when known
  try {
    const n = nodeId
      ? await db.node.findUnique({ where: { id: nodeId } })
      : await db.node.findFirst({ where: { isPrimary: true } });
    if (n) {
      const client = pveFor({
        apiUrl: n.apiUrl,
        pveNode: n.pveNode,
        tokenId: n.tokenId,
        tokenSecret: n.tokenSecret,
      });
      const st = await client.get(`/nodes/${n.pveNode}/storage/${n.storageNvme}/status`);
