 * The REAL, pre-checkout capacity check — reuses the exact oversell guards
 * lib/order.ts placeOrder / lib/game-order.ts placeGameOrder already run for
 * every premade-plan order (capacityCheckRamMB mirrors capacityCheck;
 * diskCapacityCheck is the identical function). A custom spec can ask for more
 * RAM than ANY catalog plan, so it must be screened the same way — this is not
 * a second, weaker guard, it's the same one with a raw RAM/disk number instead
 * of a `Plan` row backing it.
 */
export async function customPlanCapacityCheck(spec: CustomPlanSpec): Promise<{ ok: boolean; reason?: string }> {
  // `reason` is the customer-facing sales wording for EVERY failure (RAM, no
  // schedulable node, disk pool). The underlying guards' own reasons ("The host
  // is at capacity...", "This node's storage pool is nearly full...") are written
  // for a premade plan at checkout and are exactly the copy the owner flagged.
  // The gate itself is unchanged: a failing spec still can't be bought.
  const ramOk = await capacityCheckRamMB(spec.ramMB);
  if (!ramOk.ok) return { ok: false, reason: CUSTOM_PLAN_NEEDS_SALES_REASON };
  // Which node WOULD take this — same scheduler VPS/game orders use — so the disk
  // check below runs against a real candidate node's pool, not "any node".
  const node = await scheduleNode(spec.ramMB);
  if (!node) return { ok: false, reason: CUSTOM_PLAN_NEEDS_SALES_REASON };
  const disk = await diskCapacityCheck(node.id, spec.diskGB);
  return disk.ok ? disk : { ok: false, reason: CUSTOM_PLAN_NEEDS_SALES_REASON };
}

