type NeedsSales = { needsSales?: boolean };

/**
 * Create the one-off VPS `Plan` row for this exact spec. Called ONCE, when the
 * customer commits to their custom build (not on every slider tick) — the
 * returned plan's `id` then flows through the wizard's existing `planId` state
 * exactly like picking any premade plan card, so Location/Install/Access/Review/
 * Payment need no changes at all.
 */
export async function confirmCustomPlanAction(input: {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
}): Promise<{ ok: boolean; error?: string; plan?: ConfirmedCustomPlan } & NeedsSales> {
  await requireUser();
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const parsed = specSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
  try {
    const plan = await createCustomPlan(parsed.data);
    return { ok: true, plan: { ...plan, termMonthlyCents: await termMonthlyMatrix(plan.priceCents) } };
  } catch (e) {
    if (e instanceof CustomPlanCapacityError) return { ok: false, error: e.message, needsSales: true };
    if (e instanceof CustomPlanError) return { ok: false, error: e.message };
    return { ok: false, error: "Couldn't set up that custom server. Please try again." };
  }
}

