// Job types whose terminal failure genuinely leaves the VM in a bad/unknown
// run or disk state — only these should mark the server ERROR. Everything else
// (backup, snapshot-create, control-panel ops, SSL, migrate copy, game update…)
// is a side operation that doesn't touch the VM's run state.
//
// DISK_EXPAND is deliberately ABSENT: growing a disk never changes the VM's run
// state, so a failed expansion must leave the server RUNNING/STOPPED as it was.
// Its money is unwound by reconcileFailedJob instead.
const VM_STATE_FAILURE_JOBS = new Set<string>([
  "PROVISION", "REINSTALL", "DELETE", "RESIZE", "START", "STOP",
  "REBOOT", "SUSPEND", "UNSUSPEND", "BACKUP_RESTORE", "SNAPSHOT_ROLLBACK",
  // Same reasoning as RESIZE: it power-cycles the VM to apply a new net0/
  // ipconfig0, so a failure partway through can leave it mid-power-cycle.
  "ASSIGN_DEDICATED_IP",
]);

function generatePassword(): string {
  // URL-safe, no ambiguous chars, 16 chars
  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
}

/**
 * Guest memory / ballooning — see lib/vm-memory-policy.ts for the full story.
 *
 * History: until 2026-09-14 VMs had no balloon floor (`memory:` was a hard
 * reservation and the primary OOM-crashed). From 2026-09-14 every VM got a
 * 50% floor (min 1024), which let pvestatd squeeze a paying customer's 4 GB
 * Valheim VM to ~1.8 GB on a busy node-4 (2026-10-01). Now customer VMs get a
 * floor EQUAL to their RAM (NXEON_BALLOON_POLICY=pin, default; `off` =
 * balloon 0; `floor` = the old 50% as an emergency escape hatch), and the
 * host-side protection the floor used to give moved to the scheduler's live
 * RAM guard (lib/node-ram-guard.ts), which refuses to place pinned RAM a
 * node cannot physically back.
 */
function balloonForVm(memoryMB: number): number {
  return balloonFor(memoryMB, balloonPolicy());
}

async function loadServer(job: Job): Promise<Server & { plan: any; gamePlan: any; osTemplate: any; node: any; user: any }> {
  const server = await db.server.findUnique({
    where: { id: job.serverId! },
    // `user` (email) + `node` (publicIp) are needed for the deployment
    // confirmation email fired on provision success; the rest is used throughout.
    // `gamePlan` — a game order's REAL entitlement (its own ramMB/cpuCores/
    // diskGB, the exact numbers advertised and sold), not `plan` (the linked
    // basePlan, which only exists because the host only offers 4 discrete VPS
    // tiers and a game plan's advertised size gets rounded UP to the nearest
    // one that fits — see the long comment where cfg.memory/cores are set).
    include: { plan: true, gamePlan: true, osTemplate: true, node: true, user: { select: { id: true, email: true } } },
  });
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  return server as any;
}

/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
async function nodeFor(server: any) {
  const n =
    server.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    // No Node rows yet — use the env-configured primary via the global client.
    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
  }
  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
}

/** YAML-safe indent of a multi-line script under a `content: |` block. */
function indentBlock(text: string, spaces: number): string {
  const pad = " ".repeat(spaces);
  return text.split("\n").map((l) => pad + l).join("\n");
}

/**
 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
 * plus any control-panel/app install script and selected add-ons. Long installs
 * run in the background so the VM reports ready promptly.
 */
/**
 * The nxeon-shipper install: fetch the static binary, drop its config (server
 * id + per-server token minted by the caller, see provision()), install the
 * systemd unit, and start it. Idempotent (safe to re-run on a retried
 * provision) and — like the Claude CLI install — backgrounded via the outer
 * nohup so a slow/blocked download never delays the VM reporting ready.
 *
 * `curl -fsSL … | sh`-style external installs are the established convention
 * here (see get.docker.com / claude.ai/install.sh above); this one pulls from
 * our own APP_URL instead of a third party since the binary is ours.
 */
function shipperInstallScript(serverId: string, token: string, nodeKind: "VPS" | "GAME"): string {
  const appUrl = process.env.APP_URL ?? "https://nxeon.cloud";
  const config = JSON.stringify({
    server_id: serverId,
    token,
    ingest_url: `${appUrl}/api/telemetry/ingest`,
    node_kind: nodeKind,
  });
  return [
    "mkdir -p /etc/nxeon",
    `cat > /etc/nxeon/shipper.json <<'NXTJSON'\n${config}\nNXTJSON`,
    "chmod 600 /etc/nxeon/shipper.json",
    `curl -fsSL "${appUrl}/dl/nxeon-shipper-linux-amd64" -o /usr/local/bin/nxeon-shipper.tmp && ` +
      "chmod +x /usr/local/bin/nxeon-shipper.tmp && mv /usr/local/bin/nxeon-shipper.tmp /usr/local/bin/nxeon-shipper",
    `curl -fsSL "${appUrl}/dl/nxeon-shipper.service" -o /etc/systemd/system/nxeon-shipper.service`,
    "systemctl daemon-reload && systemctl enable --now nxeon-shipper",
  ].join("\n");
}

