import "server-only";
import type { Role } from "@prisma/client";
import { db } from "@/lib/db";
import { canAccess } from "@/lib/rbac";
import { isFleetDimension } from "@/lib/fleet-alert-plan";
import { regionAvailability } from "@/lib/node-capacity";
import { customerRegionLabel } from "@/lib/node-regions";
import type { ShellAlert } from "@/components/admin/shell/types";

/**
 * Live "needs attention" items for the admin shell's alerts tray, from real
 * rows only — nothing here is estimated. READ-ONLY.
 *
 * Used twice: server-side by app/admin/layout.tsx (so the tray and its badge
 * are correct on first paint) and by GET /api/admin/alerts, which the tray
 * polls while a tab is open. Each query fails soft to "nothing to report" so a
 * missing table or transient DB error can never break the admin layout.
 * Filtered by RBAC area: a SUPPORT account sees ticket/chat items, not fleet.
 */
export async function loadShellAlerts(role: Role): Promise<ShellAlert[]> {
  const since24h = new Date(Date.now() - 24 * 3600_000);
  const soft = <T,>(p: Promise<T>, fb: T) => p.catch(() => fb);
  const fleet = canAccess(role, "fleet");
  const tickets = canAccess(role, "supportTickets");
  const chat = canAccess(role, "liveChat");

  const [failedJobs, failedCount, nodeAlerts, abuseOpen, migrations, awaiting, oldestAwaiting, chatUnread] =
    await Promise.all([
      fleet
        ? soft(
            db.job.findMany({
              where: { status: "FAILED", updatedAt: { gte: since24h } },
              select: { id: true, type: true, error: true, updatedAt: true, server: { select: { id: true, hostname: true } } },
              orderBy: { updatedAt: "desc" },
              take: 3,
            }),
            [],
          )
        : Promise.resolve([]),
      fleet ? soft(db.job.count({ where: { status: "FAILED", updatedAt: { gte: since24h } } }), 0) : Promise.resolve(0),
      fleet
        ? soft(
            db.nodeAlert.findMany({
              where: { status: "OPEN" },
              select: { id: true, nodeName: true, dimension: true, severity: true, pct: true, detail: true, updatedAt: true },
              orderBy: { updatedAt: "desc" },
              take: 5,
            }),
            [],
          )
        : Promise.resolve([]),
      fleet ? soft(db.abuseAlert.count({ where: { status: "OPEN" } }), 0) : Promise.resolve(0),
      fleet ? soft(db.migration.count({ where: { status: { in: ["COMPLETED_WITH_ISSUES", "FAILED"] } } }), 0) : Promise.resolve(0),
      tickets ? soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } }), 0) : Promise.resolve(0),
      tickets
        ? soft(
            db.ticket.findFirst({
              where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } },
              orderBy: { updatedAt: "asc" },
              select: { updatedAt: true },
            }),
            null,
          )
        : Promise.resolve(null),
      chat ? soft(db.chatConversation.count({ where: { unreadForAgent: true } }), 0) : Promise.resolve(0),
    ]);

  const out: ShellAlert[] = [];
  // REGION FULL (2026-10-01): a region the order scheduler would refuse is
  // "sold out" for customers (the wizard shows it, and checkout refuses rather
  // than overflowing into another region). Say so, with how many orders were
  // turned away in the last 24h (AuditLog order.region_full) — lost demand.
  if (fleet) {
    const [avail, refused] = await Promise.all([
      soft(regionAvailability(2048), {} as Record<string, "available" | "limited" | "sold_out">),
      soft(db.auditLog.count({ where: { action: "order.region_full", createdAt: { gte: since24h } } }), 0),
    ]);
    const full = Object.entries(avail).filter(([, v]) => v === "sold_out").map(([k]) => customerRegionLabel(k));
    if (full.length > 0 || refused > 0) {
      out.push({
        id: "regions:full",
        tone: "red",
        title: full.length > 0 ? `Region full: ${full.join(", ")}` : `${refused} order${refused === 1 ? "" : "s"} refused: region full (24h)`,
        detail:
          (full.length > 0 ? "New orders there are refused (nothing is overflowed to another region). " : "") +
          (refused > 0 ? `${refused} order attempt${refused === 1 ? "" : "s"} turned away in the last 24h.` : "Add capacity or re-enable a node."),
        href: "/admin/nodes",
      });
    }
  }
  for (const a of nodeAlerts) {
    out.push({
      id: `node:${a.id}`,
      tone: a.severity === "CRITICAL" ? "red" : "amber",
      title: a.dimension.startsWith("OVH-GAME-FW:") ? `${a.nodeName}: OVH game firewall strict mode on ${a.dimension.slice(12)}` : a.dimension.startsWith("OVH-NET-FW:") ? `${a.nodeName}: OVH network firewall enabled on ${a.dimension.slice(11)}` : isFleetDimension(a.dimension) ? `${a.nodeName}: ${a.dimension.replace(":", " ")}` : `${a.nodeName}: ${a.dimension} at ${a.pct}%`,
      detail: a.detail,
      href: "/admin/nodes",
      at: a.updatedAt.toISOString(),
    });
  }
  if (failedCount > 0) {
    out.push({
      id: "jobs:failed",
      tone: "red",
      title: `${failedCount} failed job${failedCount === 1 ? "" : "s"} in the last 24h`,
      detail: failedJobs
        .map((j) => `${j.type.toLowerCase().replace(/_/g, " ")}${j.server ? ` · ${j.server.hostname}` : ""}`)
        .join(" — "),
      href: "/admin/jobs",
      at: failedJobs[0]?.updatedAt.toISOString(),
    });
  }
  if (awaiting > 0) {
    out.push({
      id: "tickets:awaiting",
      tone: "blue",
      title: `${awaiting} ticket${awaiting === 1 ? "" : "s"} awaiting a reply`,
      detail: oldestAwaiting ? `oldest waiting since ${oldestAwaiting.updatedAt.toISOString().slice(0, 16).replace("T", " ")} UTC` : undefined,
      href: "/admin/support",
    });
  }
  if (chatUnread > 0) {
    out.push({ id: "chat:unread", tone: "blue", title: `${chatUnread} unread live chat${chatUnread === 1 ? "" : "s"}`, href: "/admin/chat" });
  }
  if (abuseOpen > 0) {
    out.push({ id: "abuse:open", tone: "amber", title: `${abuseOpen} open abuse alert${abuseOpen === 1 ? "" : "s"}`, href: "/admin/abuse" });
  }
  if (migrations > 0) {
    out.push({
      id: "migrations",
      tone: "amber",
      title: `${migrations} migration${migrations === 1 ? "" : "s"} need${migrations === 1 ? "s" : ""} attention`,
      href: "/admin/migrations",
    });
  }
  return out;
}

