      priority: args.priority ?? "NORMAL",
      userId: args.userId,
      messages: { create: { body: args.body, authorId: args.userId, isStaff: false } },
    },
  });
  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
  await db.notification.createMany({
    data: admins.map((a) => ({
      userId: a.id,
      title: `New ticket: ${args.subject}`,
      href: `/admin/support/${ticket.id}`,
    })),
  });
  return { ticketId: ticket.id, subject: args.subject };
}

