type TicketForChannel = { id: string; subject: string; priority: string; userId: string };

/** Create the ticket's Discord channel + post the opening context message if
 *  it doesn't have one yet; return the (existing or new) channel id. */
async function ensureTicketChannel(ticket: TicketForChannel & { discordThreadId?: string | null }): Promise<string | null> {
  const existing = (ticket as { discordThreadId?: string | null }).discordThreadId;
  if (existing) return existing;

  const user = await db.user.findUnique({ where: { id: ticket.userId }, select: { name: true, email: true } });
